const data = $input.first().json;
const tasks = data.tasksDueToday || [];
const overdue = data.overdueTasks || [];

// Generate realistic non-overlapping timeblock suggestions
const suggestions = [];
let currentHour = 9;
let currentMin = 30;

const allPriorities = [...overdue, ...tasks].slice(0, 4);
for (const t of allPriorities) {
  const duration = t.estimatedMinutes || 45;
  const startStr = `${String(currentHour).padStart(2, '0')}:${String(currentMin).padStart(2, '0')}`;

  let endMin = currentMin + duration;
  let endHour = currentHour + Math.floor(endMin / 60);
  endMin = endMin % 60;
  const endStr = `${String(endHour).padStart(2, '0')}:${String(endMin).padStart(2, '0')}`;

  suggestions.push(`${startStr} - ${endStr}: ${t.title} (${duration}m, ${t.priority})`);

  // Add 15 min buffer
  currentMin = (endMin + 15) % 60;
  currentHour = endHour + Math.floor((endMin + 15) / 60);
}

if (!suggestions.length) {
  suggestions.push('Flexible Focus: Plan your key priorities in TaskPilot AI.');
}

return [{
  json: {
    ...data,
    suggestions,
    emailSubject: data.email?.subject || `Morning Briefing: Your Focus for ${data.date}`,
    emailHtml: data.email?.html,
    emailText: data.email?.text,
  }
}];
